function showMenu(){showModal('일시정지',`<div class="menu-list"><button id="menu-notes" class="action">${icon('book')}수첩</button><button id="menu-evidence" class="action">${icon('search')}현재 화면 조사 목록</button><button id="menu-display" class="action">${icon('settings')}화면·소리 설정</button><button id="menu-new" class="action danger">${icon('restart')}새 게임</button></div><p class="subtle" style="margin-top:22px">획득과 해독은 자동 저장됩니다. 현재 회전·접기의 미완료 단계는 재실행 시 처음으로 돌아갑니다.</p><p class="subtle">플레이 시간 ${formatTime(game.state.elapsedSec)} · 힌트 ${game.state.metrics.hints}회</p>`,[{label:'이어서 플레이',primary:true,run:()=>closeModal()}],'menu','PAUSED / PROGRESS SAVED');$('#menu-notes').onclick=showNotebook;$('#menu-display').onclick=showSettings;$('#menu-new').onclick=confirmNewGame;$('#menu-evidence').onclick=showSceneList;}
function showSceneList(){const s=screen();const special=s.id==='S03'?[{id:f().coatMoved?'bag':'coat',name:f().coatMoved?'가방':'외투'},...(!f().rearBeltReleased&&f().coatMoved?[{id:'rearBelt',name:'가방 고정 벨트'}]:[])]:s.id==='S05'&&v().seatPosition>=99&&!f().seatToolCollected?[{id:'tool',name:'삼각 수동 도구'}]:[];showModal(s.name+' · 조사 목록',`<p>작은 물건을 누르기 어려울 때 목록으로 선택할 수 있습니다.</p><div class="scene-list">${[...s.hotspots,...special].map(h=>`<button class="action" data-list-object="${h.id}">${esc(h.name)}</button>`).join('')}</div>`,[],'menu');$$('[data-list-object]').forEach(b=>b.onclick=()=>{const id=b.dataset.listObject;closeModal(false);interact(id);});}
function showSettings(){showModal('화면과 소리',`<div class="settings-row"><span>환경음과 효과음</span><button id="settings-sound" class="action">${muted?'꺼짐':'켜짐'}</button></div><div class="settings-row"><span>조사할 곳 은은하게 표시</span><button id="settings-assist" class="action">${assist?'켜짐':'꺼짐'}</button></div><div class="settings-row"><span>글자 크기</span><select id="font-size" class="action" aria-label="글자 크기"><option value="1">100%</option><option value="1.3">130%</option><option value="1.5">150%</option></select></div><p class="subtle" style="margin-top:20px">1~6 시점 전환 · N 수첩 · H 조사 표시 · Esc 닫기</p><p class="subtle">차량 기능은 게임 내 시뮬레이션입니다.</p><h3>앱 창 크기 검토</h3><p class="subtle">선택한 dp 크기로 검토합니다. 실제 창에서는 현재 가용 영역에 맞춰 자동 배치됩니다.</p><div class="review-controls">${PROFILES.map(p=>`<button class="action" data-profile="${p.id}">${esc(p.label)}<br>${p.windowDp.join('×')}</button>`).join('')}</div><button id="display-reset" class="action" style="margin-top:14px">현재 창에 맞추기</button>`,[],'settings');$('#settings-sound').onclick=()=>{toggleSound();$('#settings-sound').textContent=muted?'꺼짐':'켜짐'};$('#settings-assist').onclick=()=>{toggleAssist();$('#settings-assist').textContent=assist?'켜짐':'꺼짐'};$('#font-size').value=String(document.documentElement.style.getPropertyValue('--font-scale')||1);$('#font-size').onchange=e=>document.documentElement.style.setProperty('--font-scale',e.target.value);$$('[data-profile]').forEach(b=>b.onclick=()=>setProfile(b.dataset.profile));$('#display-reset').onclick=()=>setProfile(null);}
