function newGame(){stopRecording();game=new ResidualRules.Game();game.a.duration=duration();saveBlocked=false;loadStatus='new';selected=[];endingActive=false;$('#ending').classList.remove('visible');$('#intro').hidden=true;closeModal(false);game.dispatch('start');externalPause=false;menuPause=false;syncPaused();renderWorld();renderInventory();save();startAmbient();toast('낯선 운전석. 빗소리와 경고음이 들린다.');}
